<?php
/** Passive process/socket evidence. Never boot Laravel, request an endpoint or execute DML. */
require_once __DIR__.'/release-process-fence.php';
function writerRuntimeSessions(PDO $db):array {
    $rows=$db->query('SELECT ID,USER,HOST,DB,COMMAND FROM information_schema.PROCESSLIST')->fetchAll(PDO::FETCH_ASSOC);$fds=[];
    try{foreach($db->query("SELECT t.PROCESSLIST_ID id,s.SOCKET_ID fd FROM performance_schema.socket_instances s JOIN performance_schema.threads t ON t.THREAD_ID=s.THREAD_ID WHERE s.EVENT_NAME='wait/io/socket/sql/client_connection' AND t.PROCESSLIST_ID IS NOT NULL")->fetchAll(PDO::FETCH_ASSOC)as$r)$fds[(string)$r['id']]=$r['fd'];}catch(PDOException){}
    $out=[];foreach($rows as$r)$out[(string)$r['ID']]=['id'=>(string)$r['ID'],'user'=>$r['USER'],'host'=>$r['HOST'],'db'=>$r['DB'],'command'=>$r['COMMAND'],'server_fd'=>$fds[(string)$r['ID']]??null];return$out;
}
function writerKernelProbe(array $sessions,int $serverPid,int $port,int $siteUid,string $backend):array {
    $clean=array_map(fn($r)=>['id'=>$r['id'],'host'=>$r['host'],'server_fd'=>$r['server_fd']],array_values($sessions));$pipes=[];$p=proc_open(['python3',__DIR__.'/writer-kernel-links.py'],[0=>['pipe','r'],1=>['pipe','w'],2=>['file','/dev/null','w']],$pipes);if(!is_resource($p))throw new RuntimeException('KERNEL_PROBE_START_FAILED');$bytes=json_encode(['server_pid'=>$serverPid,'server_port'=>$port,'site_uid'=>$siteUid,'backend'=>$backend,'sessions'=>$clean],JSON_THROW_ON_ERROR);if(strlen($bytes)>1048576)throw new RuntimeException('SESSION_SCOPE_LIMIT');fwrite($pipes[0],$bytes);fclose($pipes[0]);$answer=stream_get_contents($pipes[1],4194305);fclose($pipes[1]);$code=proc_close($p);if(strlen($answer)>4194304)throw new RuntimeException('KERNEL_REPLY_LIMIT');$v=json_decode($answer,true,512,JSON_THROW_ON_ERROR);if($code!==0||isset($v['blocked']))throw new RuntimeException(preg_match('/^[A-Z0-9_]+$/D',$v['blocked']??'')?$v['blocked']:'KERNEL_PROOF_UNAVAILABLE');return$v;
}
function writerRuntimeCandidate(string $user,array $inventory,array $plugins,bool $anonymous):?string {
    $matches=array_values(array_filter($inventory,fn($a)=>releasePrincipalUser($a['principal'])===$user));if($anonymous||count($matches)!==1||($matches[0]['proxy_privilege_present']??false)||!in_array($plugins[$matches[0]['principal']]??'',['caching_sha2_password','sha256_password','mysql_native_password'],true))return null;return$matches[0]['principal'];
}
function writerPassiveSample(PDO $db,array $inventory,int $serverPid,int $port,int $siteUid,string $backend,array $plugins,bool $anonymous):array {
    $current=(string)$db->query('SELECT CONNECTION_ID()')->fetchColumn();$users=array_unique(array_map(fn($a)=>releasePrincipalUser($a['principal']),$inventory));$all=writerRuntimeSessions($db);$first=array_filter($all,fn($r)=>$r['id']!==$current&&($r['db']==='sulbprod'||in_array($r['user'],$users,true)));$kernel=writerKernelProbe($first,$serverPid,$port,$siteUid,$backend);$second=writerRuntimeSessions($db);$proved=[];$unresolved=$kernel['unmapped'];
    foreach($kernel['matches']as$m){$id=$m['connection_id'];$before=$first[$id]??null;$after=$second[$id]??null;$authenticated=['Sleep','Query','Execute','Fetch','Prepare','Close stmt','Long Data','Reset stmt','Ping','Init DB','Statistics'];if(!$before||!$after||!in_array($before['command'],$authenticated,true)||!in_array($after['command'],$authenticated,true)){$unresolved[]=['connection_id'=>$id,'reason'=>'AUTHENTICATION_PHASE_UNPROVEN'];continue;}$left=$before;$right=$after;unset($left['command'],$right['command']);if($left!==$right){$unresolved[]=['connection_id'=>$id,'reason'=>'MYSQL_SESSION_CHANGED'];continue;}$principal=writerRuntimeCandidate($before['user'],$inventory,$plugins,$anonymous);if(!$principal){$unresolved[]=['connection_id'=>$id,'reason'=>'AMBIGUOUS_OR_NON_DIRECT_AUTHENTICATION'];continue;}$client=releaseProcess((int)$m['pid']);if(!$client||$client['start_ticks']!==$m['start_ticks']||$client['uid']!==$m['uid']||@readlink('/proc/'.$m['pid'].'/fd/'.$m['client_fd'])!=='socket:['.$m['client_inode'].']'||@readlink('/proc/'.$serverPid.'/fd/'.$m['server_fd'])!=='socket:['.$m['server_inode'].']'){$unresolved[]=['connection_id'=>$id,'reason'=>'FINAL_SOCKET_IDENTITY_CHANGED'];continue;}$unit=null;$group=@file_get_contents('/proc/'.$m['pid'].'/cgroup');if(is_string($group)&&preg_match('#/([A-Za-z0-9_.@-]+\.service)(?:/|$)#',$group,$unitMatch))$unit=$unitMatch[1];$proved[]=$m+['unit'=>$unit,'executable_basename'=>basename($client['exe']),'principal_candidate'=>$principal,'authenticated_login_username'=>$before['user'],'selected_grant_host_proven'=>false,'authentication_account_history_verified'=>false,'selected_database_is_source'=>$before['db']==='sulbprod','principal_basis'=>'CURRENT_UNIQUE_ACCOUNT_CANDIDATE_NOT_SESSION_CURRENT_USER','observed_utc'=>gmdate('c')];}
    return ['bindings'=>$proved,'unresolved'=>$unresolved,'limitations'=>$kernel['limitations'],'coverage'=>$kernel['coverage'],'private_php_candidates'=>$kernel['private_php_candidates'],'relevant_sessions_observed'=>count($first),'site_processes_observed'=>$kernel['site_processes_observed']];
}
function writerSourceReview(array $candidate,string $backend):array {
    $path=$candidate['path'];if(!is_file($path)||realpath($path)!==$path||filesize($path)>1048576||!hash_equals($candidate['sha256'],hash_file('sha256',$path)))throw new RuntimeException('S01_SOURCE_CHANGED');$queue=[[$path,0]];$seen=[];$out=[];
    while($queue){[$file,$depth]=array_shift($queue);if(isset($seen[$file]))continue;if(count($seen)>=8)throw new RuntimeException('SCRIPT_REVIEW_FILE_LIMIT');$seen[$file]=true;if(!is_file($file)||realpath($file)!==$file||filesize($file)>1048576||str_contains($file,'/storage/')||str_contains($file,'/uploads/')){$out[]=['path'=>$file,'status'=>'PRIVATE_MANUAL_REVIEW_REQUIRED'];continue;}$text=file_get_contents($file);if($text===false)throw new RuntimeException('SCRIPT_READ_FAILED');preg_match_all('#/[A-Za-z0-9_./@+-]+\.(?:sh|php|py)\b#',$text,$m);$refs=array_values(array_unique($m[0]));if(str_contains($text,'artisan')&&str_contains($text,$backend))$refs[]=$backend.'/artisan';$st=stat($file);$out[]=['path'=>$file,'file_uid'=>$st['uid'],'file_gid'=>$st['gid'],'mode_octal'=>sprintf('%04o',$st['mode']&0777),'sha256'=>hash('sha256',$text),'dynamic_references_present'=>str_contains($text,'$')||str_contains($text,'`'),'literal_script_reference_count'=>count($refs),'content_review'=>'STATIC_REFERENCES_ONLY_NOT_EXECUTED'];if($depth<2)foreach($refs as$ref)$queue[]=[$ref,$depth+1];unset($text);}
    $console=$backend.'/routes/console.php';if(is_file($console)&&!is_link($console)&&filesize($console)<=1048576)$out[]=['path'=>$console,'sha256'=>hash_file('sha256',$console),'content_review'=>'REGISTERED_SCHEDULER_SOURCE_REQUIRES_OWNER_REVIEW'];return ['files'=>$out,'external_writers_and_schedules_reviewed'=>false,'commands_executed'=>false];
}
